import {currentPublicProfile} from './self-comparison.mjs';
import {selectForAI} from './ai-input.mjs';
import {personalInput,personalServiceProfile,PERSONAL_SCOPES} from './personal-input.mjs';

const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={situation:'Jak by to mohlo vypadat',useful:'Co si můžeš vyzkoušet',watch:'Čeho si všímat'};
const feedbackLabels={yes:'Sedí',sometimes:'Někdy',no:'Nesedí'};
export function createPersonal({show,getPersonality,getIntimacy}){
  let scopes=['personality'],report=null,busy=false,error='',feedback={},revision=0,controller=null;
  const fingerprint=()=>JSON.stringify([getPersonality(),getIntimacy()]);
  let last=fingerprint();
  const selected=()=>selectForAI(currentPublicProfile(getPersonality(),getIntimacy(),scopes),scopes);
  function clear(){revision++;controller?.abort();controller=null;report=null;busy=false;error='';feedback={};last=fingerprint();}
  function invalidate(){if(last!==fingerprint())clear();}
  const value=f=>typeof f.value==='number'?`${f.value.toLocaleString('cs-CZ',{maximumFractionDigits:2})} / 5`:f.value;
  function facts(input,scope){return input.facts.filter(f=>!scope||f.scope===scope).map(f=>`<article class="personal-fact"><div><strong>${esc(f.name)}</strong><span>${esc(value(f))}</span></div><p>${esc(f.reading)}</p><p class="small">${esc(f.limit)}</p><p><strong>K zamyšlení:</strong> ${esc(f.question)}</p></article>`).join('');}
  function content(){
    const input=personalInput(selected(),scopes);
    if(!input.facts.length)return `<div class="paper"><h2>Nejprve potřebujeme tvoje odpovědi.</h2><p>Ve vybraných oblastech zatím není co vyložit. Osobnostní škálu počítáme až ze všech deseti položek; ostatní odpovědi neodhadujeme.</p><a class="button secondary" href="#profil">Otevřít můj profil →</a></div>`;
    let html=report?.mode==='ai'?`<div class="personal-intro"><span class="eyebrow">AI VÝKLAD · NÁMĚTY K OVĚŘENÍ</span><h2>Výsledek je začátek.<br><em>Souvislosti doplníš ty.</em></h2><p>Příklady níže jsou vymyšlené situace, ne zjištění o tvém životě. I přesvědčivý text se může mýlit. U každé kapitoly hledej jeden příklad pro a jeden proti.</p></div>${report.chapters.map(ch=>`<article class="paper personal-chapter"><span class="eyebrow">${esc(PERSONAL_SCOPES[ch.scope])}</span><section class="personal-grounded"><h3>Co říkají odpovědi</h3><p class="small">Výklad podle pravidel · bez AI</p>${input.facts.filter(f=>f.scope===ch.scope).map(f=>`<p><strong>${esc(f.name)}:</strong> ${esc(f.reading)}</p>`).join('')}</section><span class="eyebrow">AI / MOŽNÉ SOUVISLOSTI K OVĚŘENÍ</span>${Object.entries(labels).map(([key,label])=>`<section><h3>${label}</h3><p>${esc(ch[key])}</p></section>`).join('')}<div class="personal-check"><h3>Zkus to porovnat se zkušeností</h3><p><strong>Kdy to sedí?</strong> ${esc(ch.fits)}</p><p><strong>Kdy to nesedí?</strong> ${esc(ch.exception)}</p></div><fieldset class="personal-feedback"><legend>Jak ti tato kapitola sedí?</legend>${Object.entries(feedbackLabels).map(([key,label])=>`<button class="button secondary" type="button" data-personal-feedback="${ch.scope}" data-fit="${key}" aria-pressed="${feedback[ch.scope]===key}">${label}</button>`).join('')}</fieldset><details class="personal-evidence"><summary>Podklady této kapitoly · ${input.facts.filter(f=>f.scope===ch.scope).length} hodnot</summary><p class="small">Původní hodnoty a vysvětlení podle pravidel. Tato část není generovaná AI. Kapitola pracuje s těmito podklady; nejde o důkaz správnosti každé její věty.</p>${facts(input,ch.scope)}</details></article>`).join('')}<aside class="paper personal-takeaway"><h2>Co si z toho odnést</h2><p id="personal-feedback-summary">${feedbackSummary()}</p><p>Vyber si jednu situaci, kterou budeš pár dní sledovat. Všímej si i opačných příkladů. To, co nesedí, můžeš bez obhajování odložit; pocit shody není ověřením přesnosti testu.</p></aside>`:'';
    if(report&&report.mode!=='ai')html+=`<p class="notice">${esc(report.message||'AI výklad nyní není dostupný. Tvoje výsledky zůstávají níže.')}</p>`;
    if(input.facts.some(f=>f.scope==='practices'))html+=`<section class="paper"><span class="eyebrow">TVOJE PŘESNÉ VOLBY · BEZ AI</span><h2>Preference a hranice vlastními odpověďmi</h2><p>„Možná“ zůstává možností, „nevím“ neznámou a „nechci“ hranicí. Tyto volby modelu neposíláme a nepřepisujeme je volným výkladem.</p>${facts(input,'practices')}</section>`;
    if(report?.mode!=='ai')html+=`<section class="paper"><span class="eyebrow">VÝSLEDKY PODLE PRAVIDEL · BEZ AI</span><h2>Z čeho rozbor vychází</h2>${Object.keys(PERSONAL_SCOPES).filter(s=>s!=='practices'&&input.facts.some(f=>f.scope===s)).map(s=>`<details class="personal-evidence"><summary>${esc(PERSONAL_SCOPES[s])}</summary>${facts(input,s)}</details>`).join('')}<p>Chybějící odpovědi se neodhadují. AI doplní souvislý výklad až po tvém kliknutí výše.</p></section>`;
    if(input.missing.length)html+=`<p class="fine-print">Ve vybraných kategoriích chybí ${input.missing.length} hodnot. Rozbor je nedoplňuje a může popsat jen dostupnou část.</p>`;
    return html;
  }
  function feedbackSummary(){const entries=Object.entries(feedback);return entries.length?entries.map(([scope,fit])=>`${PERSONAL_SCOPES[scope]}: ${feedbackLabels[fit].toLowerCase()}.`).join(' ')+' Je to tvoje poznámka k výkladu, nikoli nové skóre.':'Zatím jsi žádnou kapitolu neoznačil/a. Výklad nemusí sedět celý — ani vůbec.';}
  function paint(){if(location.hash!=='#rozbor')return;document.getElementById('personal-output').innerHTML=content();const button=document.querySelector('[data-personal="generate"]');button.disabled=busy||!scopes.length||!personalInput(selected(),scopes).facts.length;button.textContent=busy?'Připravuji rozbor…':report?.mode==='ai'?'Vytvořit rozbor znovu':'Vytvořit osobní rozbor';document.getElementById('personal-status').textContent=error||(busy?'Místní model připravuje výklad. Obvykle to chvíli trvá; výsledky zůstávají níže.':report?.mode==='ai'?'Rozbor je připravený níže.':'');}
  function page(){const input=personalInput(selected(),scopes);return `<div class="wrap narrow page-head"><a class="back-link" href="#profil">← Můj profil</a><span class="eyebrow">OSOBNÍ ROZBOR</span><h1>Co si z výsledku<br><em>vzít do života?</em></h1><p class="lead">Souvislosti, příklady a otázky, které si můžeš ověřit na sobě. Konečné slovo má tvoje zkušenost.</p></div><div class="wrap narrow personal-page"><section class="paper personal-options"><h2>O čem chceš přemýšlet?</h2><p>Vyber oblasti. Intimní část přidáš pouze svou volbou.</p><fieldset><legend class="sr-only">Oblasti osobního rozboru</legend><div class="personal-scopes">${Object.entries(PERSONAL_SCOPES).map(([key,label])=>`<label><input type="checkbox" data-personal-scope="${key}" ${scopes.includes(key)?'checked':''}><span>${label}${key==='practices'?'<small>Přesné volby s vysvětlením podle pravidel</small>':''}</span></label>`).join('')}</div></fieldset><p class="small">Kliknutím odešleš vybrané podklady místní službě tohoto webu. Model dostane jen vybrané číselné výsledky; aktivity a neurčené odpovědi vyloží pravidla mimo něj. Bez přihlašovacích údajů a bez účtu.</p><div class="actions"><button class="button" data-personal="generate" ${busy||!input.facts.length||!scopes.length?'disabled':''}>${busy?'Připravuji rozbor…':report?.mode==='ai'?'Vytvořit rozbor znovu':'Vytvořit osobní rozbor'}</button><a class="text-link" href="#podklady-rozbor">Na čem to stojí →</a></div><p id="personal-status" role="status" aria-live="polite">${esc(error||(busy?'Místní model připravuje výklad…':''))}</p></section><aside class="personal-limit"><strong>Možný výklad, ne posudek.</strong> Český překlad i intimní otázky jsou nevalidované. AI může souvislosti vyložit chybně; kontrola formátu nezaručuje pravdivost. <a href="#podklady-rozbor">Zdroje a limity</a><p>Rozbor ani volby „sedí / nesedí“ se neukládají do účtu ani prohlížeče. Po obnovení stránky zmizí, i když si prohlížeč pamatuje odpovědi testů.</p></aside><div id="personal-output" tabindex="-1" role="region" aria-label="Osobní rozbor a podklady">${content()}</div></div>`;}
  async function generate(){
    if(busy)return;invalidate();const profile=selected(),input=personalInput(profile,scopes);if(!input.facts.length)return;
    clear();const current=revision,key=fingerprint(),chosen=[...scopes];controller=new AbortController();const signal=AbortSignal.any([controller.signal,AbortSignal.timeout(100000)]);busy=true;paint();
    try{
      // Activities and unknown context answers are interpreted locally; never send them to the model gateway.
      if(!input.facts.some(f=>f.modelEligible)){report={mode:'rules',message:'Tyto volby vysvětlují pravidla níže. AI není pro tento výběr potřeba.'};return;}
      const session=await fetch('./api.php',{credentials:'same-origin',cache:'no-store',signal});const info=await session.json();if(!session.ok)throw Error(info.error||'Služba není dostupná.');
      const payload=personalServiceProfile(profile,chosen);
      const response=await fetch('./api.php',{method:'POST',credentials:'same-origin',cache:'no-store',signal,headers:{'Content-Type':'application/json','X-CSRF-Token':info.csrf},body:JSON.stringify({action:'ai-personal',scopes:payload.scopes,profile:payload})});
      const data=await response.json();if(!response.ok)throw Error(data.error||'Služba není dostupná.');
      if(current===revision&&key===fingerprint())report=data;
    }catch(e){if(current===revision)error=e.name==='AbortError'||e.name==='TimeoutError'?'Čekání na AI skončilo. Můžeš to zkusit znovu; původní výsledky jsou níže.':'AI rozbor teď není dostupný. '+(e instanceof SyntaxError?'Zkus to později.':e.message);}
    finally{if(current===revision){busy=false;controller=null;paint();if(report&&location.hash==='#rozbor'){const output=document.getElementById('personal-output');output?.focus({preventScroll:true});output?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}}}
  }
  document.addEventListener('change',event=>{const scope=event.target.dataset.personalScope;if(!scope)return;clear();scopes=Object.keys(PERSONAL_SCOPES).filter(s=>s===scope?event.target.checked:scopes.includes(s));paint();});
  document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.personal==='generate')generate();if(b.dataset.personalFeedback){feedback[b.dataset.personalFeedback]=b.dataset.fit;document.querySelectorAll(`[data-personal-feedback="${b.dataset.personalFeedback}"]`).forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.getElementById('personal-feedback-summary').textContent=feedbackSummary();}});
  return {clear,reset(){clear();scopes=['personality'];},invalidate,route(hash){invalidate();if(hash==='#podklady-rozbor'){show(personalSources(),'Podklady osobního rozboru','science');return true;}if(hash!=='#rozbor')return false;show(page(),'Osobní rozbor','results');return true;}};
}

export function personalSources(){return `<div class="wrap narrow page-head"><span class="eyebrow">ZDROJE / OSOBNÍ ROZBOR</span><h1>Podklad je výsledek.<br><em>Výklad je možnost.</em></h1><p class="lead">Jazykový model pomáhá převést odpovědi do příkladů a otázek. Nemáme výzkumné ověření přesnosti tohoto osobního rozboru.</p></div><article class="wrap narrow reading"><section><h2>Co je převzaté a co naše</h2><p>Osobnost vychází z anglických položek IPIP-50 a jejich skórovacího klíče. Používáme vlastní český překlad, který není psychometricky validovaný. Intimní otázky a všechny interpretační texty jsou vlastní a také nevalidované. Validita původního nástroje ani jiné české adaptace se automaticky nepřenáší na tento web nebo AI výklad.</p><p><a href="#podklady">Položky, skórovací klíč a zdroje IPIP →</a><br><a href="#podklady-intimita">Výzkum v pozadí intimních témat a limity našich otázek →</a></p></section><section><h2>Číslo má přesný výpočet, nikoli automatický životní význam</h2><p>Odpovědi se skórují podle klíče, u obrácených položek jako 6 − odpověď. Pro úplnou škálu ukazujeme průměr. Oblasti do 2,5 a od 3,5 jsou vlastní zobrazovací konvence; střed stupnice není průměrem populace. Nemáme české normy, percentily ani intervaly spolehlivosti.</p><p>IPIP neposkytuje hotovou interpretační příručku pro individuální skóre. Naše příklady z běžného života proto označujeme jako hypotézy k vlastnímu ověření, ne závěry převzaté ze zdroje.</p><p><a href="https://ipip.ori.org/newScoringInstructions.htm" target="_blank" rel="noopener noreferrer">IPIP: pravidla skórování ↗</a><br><a href="https://ipip.ori.org/InterpretingIndividualIPIPScaleScores.htm" target="_blank" rel="noopener noreferrer">IPIP: interpretace individuálních skóre ↗</a></p></section><section><h2>Co přesně dělá AI</h2><p>Na tvůj pokyn dostane místní model vybrané dostupné číselné hodnoty a popisy podle pravidel. Neposíláme mu ID, přihlašovací či sdílecí klíče, původní položkové odpovědi IPIP ani nevybrané kategorie. Aktivity, hranice a neurčené odpovědi zůstávají mimo model. Chybějící škály nedoplňujeme.</p><p>Význam jednotlivých odpovědí vysvětlí pevná pravidla. Model doplní pro každou vybranou číselnou oblast hypotetický příklad, možnost pozorování, možné tření a otázky pro i proti výkladu. Přesná skóre zůstávají oddělená, rozbalitelná u kapitoly. Temperament znovu nehodnotí a nepropojuje povahu se sexuálními rolemi.</p><p>Kontrolujeme strukturu, délku, povolené kapitoly, podmíněné formulace a některé nepřípustné výrazy. Tyto kontroly neověřují pravdivost, psychologickou platnost ani každou možnou nepodloženou domněnku. AI může i při správném formátu vytvořit chybný nebo příliš obecný výklad. Při nedostupném či neplatném výstupu zůstanou výsledky podle pravidel.</p><p>V partnerském porovnání AI dál pouze vybírá předem napsané otázky. Volně generovaný osobní výklad je samostatná funkce.</p></section><section><h2>Jak si udělat vlastní obrázek</h2><p>Užitečnější než souhlas se vším je konkrétní příklad: kdy se tak chováš, kdy ne a co se mezi situacemi mění. Stejné skóre může vzniknout z různých odpovědí. „Nesedí“ je rovnocenný výsledek sebereflexe, nikoli chyba uživatele. Označení shody neověřuje vědeckou přesnost testu a nemění skóre.</p><p>Rozbor, příklady ani tvoje označení se automaticky neukládají. V této kartě zůstanou do změny odpovědí či výběru, smazání, odhlášení nebo obnovení stránky. <a href="#soukromi">Zpracování dat a soukromí →</a></p></section><a class="button" href="#rozbor">Otevřít osobní rozbor →</a></article>`;}
